1	//! The Node binding (NAPI) over `caliper-docgen-core`: one-shot extraction and long-lived sessions for hosts that run
2	//! in-process, such as the Vite plugin and the Storybook addon. Every entry point contains a panic and reports it
3	//! instead of crashing the host (ADR 0005).
4	
5	#![deny(missing_docs)]
6	
7	use std::sync::atomic::{AtomicU64, Ordering};
8	use std::sync::{Arc, LazyLock};
9	
10	use camino::Utf8Path;
11	use dashmap::DashMap;
12	use napi_derive::napi;
13	
14	use caliper_docgen_core::pipeline::{
15	    extraction_output_to_json, incremental_update_to_json, PipelineOptions, WatchSession,
16	};
17	
18	#[global_allocator]
19	static ALLOCATOR: mimalloc::MiMalloc = mimalloc::MiMalloc;
20	
21	// ─── Session store ────────────────────────────────────────────────────────────
22	
23	static SESSIONS: LazyLock<DashMap<u32, Arc<WatchSession>>> = LazyLock::new(DashMap::new);
24	static NEXT_SESSION_ID: AtomicU64 = AtomicU64::new(0);
25	
26	/// Src-dir value that trips a simulated panic inside `create_session`'s real
27	/// body — exists only to let tests exercise `panic_guard::contain_panic`'s
28	/// containment through the actual production entry point, the same pattern
29	/// `caliper_docgen_core::pipeline`'s `PARSE_PANIC_TEST_SENTINEL` uses.
30	#[cfg(test)]
31	const CREATE_SESSION_PANIC_TEST_SENTINEL: &str = "__CREATE_SESSION_PANIC_TEST__";
32	
33	/// Src-dir value that trips a simulated panic inside `extract_all`'s real
34	/// body (at the `pipeline::extract` step, before serialization). SPEC-BINDING-001 AC6.
35	#[cfg(test)]
36	const EXTRACT_ALL_PANIC_TEST_SENTINEL: &str = "__EXTRACT_ALL_PANIC_TEST__";
37	
38	/// Reserved `session_id` values used only by `#[cfg(test)]` sentinel checks
39	/// below, to trip a simulated panic at a SPECIFIC point in each entry
40	/// point's real body. Each targets a different point deliberately — see
41	/// SPEC-BINDING-001 AC3/AC7/AC8/AC10, which each require proving panic
42	/// containment at a *distinct* trigger site, not just "some panic somewhere
43	/// is caught":
44	///
45	/// - `AUTO_VIVIFY_PANIC_TEST_SENTINEL` fires during auto-vivified
46	///   `WatchSession` construction (the `None` branch of the SESSIONS.get
47	///   match in `initialize_session`/`extract_file_incremental`) — before the
48	///   session is registered at all.
49	/// - `INITIALIZE_SESSION_PANIC_TEST_SENTINEL` fires at `initialize_session`'s
50	///   actual core call (`session.initialize()`), reachable only for an
51	///   ALREADY-REGISTERED session — i.e. strictly after auto-vivification (or
52	///   `create_session`) has already completed. Distinct from
53	///   `AUTO_VIVIFY_PANIC_TEST_SENTINEL`'s trigger point.
54	/// - `CLOSE_SESSION_PANIC_TEST_SENTINEL` fires inside `close_session`'s body.
55	///
56	/// Chosen as the top of `u32`'s range: `next_session_id()`'s output is
57	/// `(pid & 0xFFFF) << 16 | (counter & 0xFFFF)`, so either value could
58	/// theoretically collide with a real generated ID under an astronomically
59	/// unlikely combination of process ID and call count — judged an acceptable
60	/// risk for test-only sentinels, consistent with the documented tradeoff on
61	/// `next_session_id`'s own 16-bit allocation.
62	#[cfg(test)]
63	const AUTO_VIVIFY_PANIC_TEST_SENTINEL: u32 = u32::MAX;
64	#[cfg(test)]
65	const INITIALIZE_SESSION_PANIC_TEST_SENTINEL: u32 = u32::MAX - 1;
66	#[cfg(test)]
67	const CLOSE_SESSION_PANIC_TEST_SENTINEL: u32 = u32::MAX - 3;
68	
69	/// `extract_file_incremental`'s core-call sentinel is file_path-based
70	/// instead — its core call (`session.update_file(path)`) is keyed by path,
71	/// not session_id, so a distinguishing file_path is the natural trigger for
72	/// SPEC-BINDING-001 AC8, reached only for an already-registered session,
73	/// strictly after `AUTO_VIVIFY_PANIC_TEST_SENTINEL`'s trigger point.
74	#[cfg(test)]
75	const EXTRACT_FILE_INCREMENTAL_PANIC_TEST_SENTINEL: &str = "__EXTRACT_FILE_INCREMENTAL_PANIC_TEST__";
76	
77	/// Pure bit-packing seam for `next_session_id()`, so SPEC-BINDING-001 AC4's
78	/// uniqueness claim (no duplicate for N <= 65,536 calls in one process) is
79	/// testable directly against synthetic counter values — `next_session_id()`
80	/// itself reads a real, process-global `AtomicU64` shared across every test
81	/// in this binary (including other tests' own `next_session_id()`/
82	/// `create_session()` calls), so driving 65,536 real calls through it would
83	/// risk wrapping mid-test on however much prior pollution happened to land
84	/// before this test ran, under parallel test execution.
85	fn compute_session_id(pid: u64, counter: u64) -> u32 {
86	    // Avoids session-ID collisions across concurrent Vite dev server instances.
87	    (((pid & 0xFFFF) << 16) | (counter & 0xFFFF)) as u32
88	}
89	
90	fn next_session_id() -> u32 {
91	    let pid = std::process::id() as u64;
92	    let counter = NEXT_SESSION_ID.fetch_add(1, Ordering::Relaxed);
93	    compute_session_id(pid, counter)
94	}
95	
96	// ─── JsExtractOptions ─────────────────────────────────────────────────────────
97	
98	/// Options passed from TypeScript — flat struct for easy NAPI marshalling.
99	#[napi(object)]
100	pub struct JsExtractOptions {
101	    /// Source directories to scan.
102	    pub src_dirs: Vec<String>,
103	    /// Extra glob-like patterns to exclude (on top of built-in: stories, tests, snapshots).
104	    pub exclude: Option<Vec<String>>,
105	    /// `'full'` (the default) lists all of an element's attributes, `'curated'` a compact subset, `'none'` none.
106	    #[napi(ts_type = "'curated' | 'full' | 'none'")]
107	    pub html_attributes: Option<String>,
108	    /// Path to the tsconfig that governs module resolution. When unset, each importing file uses the nearest
109	    /// `tsconfig.json` above it.
110	    pub tsconfig_path: Option<String>,
111	    /// Additional builtin type names beyond the React standard set.
112	    pub extra_builtins: Option<Vec<String>>,
113	    /// Cache directory; by default one under `node_modules/.cache/caliper-docgen` above the first source directory.
114	    pub cache_dir: Option<String>,
115	    /// Read and write the on-disk caches (default `true`). `false` reads and writes nothing under `cacheDir`; the
116	    /// output is the same.
117	    pub cache: Option<bool>,
118	    /// Load the dependency type declarations project types reference (default `true`).
119	    pub load_dependencies: Option<bool>,
120	    /// Which inherited sources of more than 30 props to list as one layer (default `'dependencies'`).
121	    #[napi(ts_type = "'dependencies' | 'all' | 'none'")]
122	    pub collapse_inherited_props: Option<String>,
123	    /// Session only (`createSession`, `initializeSession`, `extractFileIncremental`): parse and index every file, and
124	    /// resolve a component when `sessionDocgenInfo` asks for it (off by default; ADR 0016). `initializeSession` then
125	    /// returns an output with no components.
126	    pub lazy: Option<bool>,
127	    /// Session only: `'on-demand'` asks TypeScript's 7.1 checker for each component a request names, and answers
128	    /// with the structural props when the checker is slower than `semanticWaitMs` (experimental; ADR 0022). Needs
129	    /// `typescript@beta` installed or `tscPath`. `'off'` (the default) never starts it.
130	    #[napi(ts_type = "'off' | 'on-demand'")]
131	    pub semantic_types: Option<String>,
132	    /// Session only, with `semanticTypes: 'on-demand'`: the `tsc` binary to run, instead of the nearest
133	    /// `node_modules/typescript/bin/tsc`.
134	    pub tsc_path: Option<String>,
135	    /// Session only, with `semanticTypes: 'on-demand'`: how many milliseconds a request waits for the checker before
136	    /// it takes the structural answer (default 150).
137	    pub semantic_wait_ms: Option<u32>,
138	}
139	
140	/// How long a request waits for the checker when `semanticWaitMs` is not set: about the first-story budget.
141	const DEFAULT_SEMANTIC_WAIT_MS: u32 = 150;
142	
143	/// An empty session for `options`: lazy when they say so, with a checker attached when they ask for one.
144	fn new_session(options: JsExtractOptions) -> napi::Result<Arc<WatchSession>> {
145	    let lazy = options.lazy.unwrap_or(false);
146	    let semantic = match options.semantic_types.as_deref() {
147	        None | Some("off") => None,
148	        Some("on-demand") => Some((
149	            options.tsc_path.clone(),
150	            options.tsconfig_path.clone(),
151	            options.src_dirs.first().cloned(),
152	            options.semantic_wait_ms.unwrap_or(DEFAULT_SEMANTIC_WAIT_MS),
153	        )),
154	        Some(other) => {
155	            return Err(napi::Error::from_reason(format!("semanticTypes must be 'off' or 'on-demand', got '{other}'")))
156	        }
157	    };
158	    let pipeline_options = PipelineOptions::try_from(options).map_err(napi::Error::from_reason)?;
159	    let session = match lazy {
160	        true => WatchSession::lazy(pipeline_options),
161	        false => WatchSession::new(pipeline_options),
162	    };
163	    let session = match semantic {
164	        Some((tsc_path, tsconfig, first_src, wait_ms)) => {
165	            let checker = on_demand_checker(tsc_path, tsconfig, first_src);
166	            session.with_semantic(checker, std::time::Duration::from_millis(u64::from(wait_ms)))
167	        }
168	        None => session,
169	    };
170	    Ok(Arc::new(session))
171	}
172	
173	/// A warm `tsc` for the project that holds `first_src`. It starts in the background, so a request that arrives before
174	/// it is up takes the structural answer rather than waiting for the process.
175	fn on_demand_checker(
176	    tsc_path: Option<String>,
177	    tsconfig: Option<String>,
178	    first_src: Option<String>,
179	) -> Arc<caliper_docgen_semantic::OnDemand> {
180	    let root = first_src
181	        .as_deref()
182	        .and_then(|dir| std::fs::canonicalize(dir).ok())
183	        .and_then(|dir| camino::Utf8PathBuf::from_path_buf(dir).ok())
184	        .or_else(|| std::env::current_dir().ok().and_then(|dir| camino::Utf8PathBuf::from_path_buf(dir).ok()))
185	        .unwrap_or_default();
186	    let mut config = caliper_docgen_semantic::OnDemandConfig::new(root.clone());
187	    config.tsconfig = tsconfig
188	        .map(camino::Utf8PathBuf::from)
189	        .or_else(|| root.ancestors().map(|dir| dir.join("tsconfig.json")).find(|file| file.is_file()));
190	    config.tsc_path = tsc_path.map(camino::Utf8PathBuf::from);
191	    let checker = caliper_docgen_semantic::OnDemand::new(config);
192	    checker.warm_up();
193	    Arc::new(checker)
194	}
195	
196	// ─── TryFrom<JsExtractOptions> for PipelineOptions ────────────────────────────
197	
198	impl TryFrom<JsExtractOptions> for PipelineOptions {
199	    /// Names the bad `htmlAttributes` value — a typo (or a caller bypassing the TS union, e.g. via
200	    /// `as any`) must not silently fall back to a default (AGENTS.md non-negotiable #6).
201	    type Error = String;
202	
203	    fn try_from(js: JsExtractOptions) -> Result<Self, Self::Error> {
204	        use compact_str::CompactString;
205	
206	        let mut opts =
207	            PipelineOptions { src_dirs: js.src_dirs.into_iter().map(Into::into).collect(), ..Default::default() };
208	
209	        if let Some(exclude) = js.exclude {
210	            opts.exclude_patterns = exclude;
211	        }
212	        if let Some(mode) = js.html_attributes.as_deref() {
213	            opts.html_attributes = caliper_docgen_core::pipeline::HtmlAttributeMode::parse(mode)
214	                .map_err(|bad| format!("htmlAttributes is '{bad}', expected \"curated\", \"full\" or \"none\""))?;
215	        }
216	        if let Some(path) = js.tsconfig_path {
217	            opts.tsconfig_path = Some(path.into());
218	        }
219	        if let Some(names) = js.extra_builtins {
220	            opts.extra_builtins = names.into_iter().map(CompactString::from).collect();
221	        }
222	        if let Some(dir) = js.cache_dir {
223	            opts.cache_dir = Some(dir.into());
224	        }
225	        if let Some(cache) = js.cache {
226	            opts.use_cache = cache;
227	        }
228	        if let Some(load) = js.load_dependencies {
229	            opts.load_dependencies = load;
230	        }
231	        if let Some(mode) = js.collapse_inherited_props.as_deref() {
232	            opts.collapse_inherited_props = caliper_docgen_core::pipeline::CollapseInheritedProps::parse(mode)
233	                .map_err(|bad| {
234	                    format!("collapseInheritedProps is '{bad}', expected \"dependencies\", \"all\" or \"none\"")
235	                })?;
236	        }
237	
238	        Ok(opts)
239	    }
240	}
