242	// ─── Public NAPI functions ────────────────────────────────────────────────────
243	
244	/// Cold extraction — returns JSON string of ExtractionOutput.
245	/// Use for: build-time extraction, CLI backing, one-off runs.
246	#[napi]
247	pub async fn extract_all(options: JsExtractOptions) -> napi::Result<String> {
248	    let pipeline_options = PipelineOptions::try_from(options).map_err(napi::Error::from_reason)?;
249	    tokio::task::spawn_blocking(move || {
250	        match caliper_docgen_core::panic_guard::contain_panic("extract_all", move || {
251	            #[cfg(test)]
252	            if pipeline_options.src_dirs.iter().any(|d| d.as_str() == EXTRACT_ALL_PANIC_TEST_SENTINEL) {
253	                panic!("simulated extract_all panic (test-only sentinel)");
254	            }
255	
256	            let output = caliper_docgen_core::pipeline::extract(&pipeline_options);
257	            extraction_output_to_json(&output).map_err(|e| napi::Error::from_reason(e.to_string()))
258	        }) {
259	            Ok(result) => result,
260	            Err(diag) => Err(napi::Error::from_reason(diag.to_string())),
261	        }
262	    })
263	    .await
264	    .map_err(|e| napi::Error::from_reason(e.to_string()))?
265	}
266	
267	/// Create a persistent watch session. Returns session ID.
268	/// Call this in Vite's configResolved hook.
269	#[napi]
270	pub fn create_session(options: JsExtractOptions) -> napi::Result<u32> {
271	    match caliper_docgen_core::panic_guard::contain_panic("create_session", move || {
272	        #[cfg(test)]
273	        if options.src_dirs.iter().any(|d| d == CREATE_SESSION_PANIC_TEST_SENTINEL) {
274	            panic!("simulated create_session panic (test-only sentinel)");
275	        }
276	
277	        let session = new_session(options)?;
278	        let id = next_session_id();
279	        SESSIONS.insert(id, session);
280	        Ok(id)
281	    }) {
282	        Ok(result) => result,
283	        Err(diag) => Err(napi::Error::from_reason(diag.to_string())),
284	    }
285	}
