287	/// Incremental extraction for a single changed file.
288	/// Returns JSON string of IncrementalUpdate.
289	/// Use for: Vite HMR hotUpdate.
290	#[napi]
291	pub async fn extract_file_incremental(
292	    file_path: String,
293	    session_id: u32,
294	    options: JsExtractOptions,
295	) -> napi::Result<String> {
296	    tokio::task::spawn_blocking(move || {
297	        match caliper_docgen_core::panic_guard::contain_panic("extract_file_incremental", move || {
298	            let session = match SESSIONS.get(&session_id) {
299	                Some(s) => s.clone(),
300	                None => {
301	                    #[cfg(test)]
302	                    if session_id == AUTO_VIVIFY_PANIC_TEST_SENTINEL {
303	                        panic!("simulated extract_file_incremental auto-vivification panic (test-only sentinel)");
304	                    }
305	
306	                    let s = new_session(options)?;
307	                    SESSIONS.insert(session_id, s.clone());
308	                    s
309	                }
310	            };
311	
312	            #[cfg(test)]
313	            if file_path == EXTRACT_FILE_INCREMENTAL_PANIC_TEST_SENTINEL {
314	                panic!("simulated extract_file_incremental core-call panic (test-only sentinel)");
315	            }
316	
317	            let path = Utf8Path::new(&file_path);
318	            let update = session.update_file(path);
319	            incremental_update_to_json(&update).map_err(|e| napi::Error::from_reason(e.to_string()))
320	        }) {
321	            Ok(result) => result,
322	            Err(diag) => Err(napi::Error::from_reason(diag.to_string())),
323	        }
324	    })
325	    .await
326	    .map_err(|e| napi::Error::from_reason(e.to_string()))?
327	}
