329	/// The session's current output as a JSON string of ExtractionOutput, running the cold extraction first if the
330	/// session has none. Every change applied through `extract_file_incremental` is reflected.
331	#[napi]
332	pub async fn initialize_session(session_id: u32, options: JsExtractOptions) -> napi::Result<String> {
333	    tokio::task::spawn_blocking(move || {
334	        match caliper_docgen_core::panic_guard::contain_panic("initialize_session", move || {
335	            let session = match SESSIONS.get(&session_id) {
336	                Some(s) => s.clone(),
337	                None => {
338	                    #[cfg(test)]
339	                    if session_id == AUTO_VIVIFY_PANIC_TEST_SENTINEL {
340	                        panic!("simulated initialize_session auto-vivification panic (test-only sentinel)");
341	                    }
342	
343	                    let s = new_session(options)?;
344	                    SESSIONS.insert(session_id, s.clone());
345	                    s
346	                }
347	            };
348	
349	            #[cfg(test)]
350	            if session_id == INITIALIZE_SESSION_PANIC_TEST_SENTINEL {
351	                panic!("simulated initialize_session core-call panic (test-only sentinel)");
352	            }
353	
354	            let output = session.initialize();
355	            caliper_docgen_core::pipeline::extraction_output_to_json(&output)
356	                .map_err(|e| napi::Error::from_reason(e.to_string()))
357	        }) {
358	            Ok(result) => result,
359	            Err(diag) => Err(napi::Error::from_reason(diag.to_string())),
360	        }
361	    })
362	    .await
363	    .map_err(|e| napi::Error::from_reason(e.to_string()))?
364	}
365	
366	/// Like [`initialize_session`], but returns only what a host needs to find a component and judge whether its props are
367	/// complete: `{ components: { key: { filePath, displayName } }, diagnostics }`. The props stay in the session for
368	/// [`session_docgen_info`]. A host that documents one component at a time skips serializing and parsing every prop of
369	/// every component, which is tens of megabytes when dependencies are loaded.
370	#[napi]
371	pub async fn initialize_session_index(session_id: u32, options: JsExtractOptions) -> napi::Result<String> {
372	    tokio::task::spawn_blocking(move || {
373	        match caliper_docgen_core::panic_guard::contain_panic("initialize_session_index", move || {
374	            let session = match SESSIONS.get(&session_id) {
375	                Some(s) => s.clone(),
376	                None => {
377	                    let s = new_session(options)?;
378	                    SESSIONS.insert(session_id, s.clone());
379	                    s
380	                }
381	            };
382	
383	            drop(session.initialize());
384	            let output = session
385	                .current_output()
386	                .ok_or_else(|| napi::Error::from_reason("the session has no output after initialize".to_owned()))?;
387	            // A lazy session's output has no components and no component diagnostics: it resolves none of them. Where
388	            // each is declared comes from parsing, and a component's diagnostics come with its `sessionComponentAnswers`.
389	            caliper_docgen_core::pipeline::session_index_to_json(&session.component_index(), &output)
390	                .map_err(|e| napi::Error::from_reason(e.to_string()))
391	        }) {
392	            Ok(result) => result,
393	            Err(diag) => Err(napi::Error::from_reason(diag.to_string())),
394	        }
395	    })
396	    .await
397	    .map_err(|e| napi::Error::from_reason(e.to_string()))?
398	}
399	
400	/// The session's components with these keys as react-docgen-typescript documents them (`__docgenInfo`, which
401	/// Storybook converts to argTypes), as a JSON object keyed by component key. A key the session doesn't have is left
402	/// out; so is every key before the session is initialized.
403	#[napi]
404	pub fn session_docgen_info(session_id: u32, keys: Vec<String>) -> napi::Result<String> {
405	    match caliper_docgen_core::panic_guard::contain_panic("session_docgen_info", move || {
406	        let session = SESSIONS.get(&session_id).map(|session| session.clone());
407	        let docs: serde_json::Map<String, serde_json::Value> = match session {
408	            // A lazy session resolves each requested component now, and the ones it already resolved are answered
409	            // from its memo.
410	            Some(session) if session.is_lazy() => {
411	                let answers = session.components(&keys);
412	                keys.into_iter()
413	                    .zip(answers)
414	                    .filter_map(|(key, answer)| {
415	                        Some((key, caliper_docgen_core::pipeline::rdt::docgen_info(&answer?.entry)))
416	                    })
417	                    .collect()
418	            }
419	            session => {
420	                let output = session.and_then(|session| session.current_output());
421	                keys.into_iter()
422	                    .filter_map(|key| {
423	                        let entry = output.as_ref()?.components.get(&key)?;
424	                        Some((key, caliper_docgen_core::pipeline::rdt::docgen_info(entry)))
425	                    })
426	                    .collect()
427	            }
428	        };
429	        serde_json::to_string(&docs).map_err(|e| napi::Error::from_reason(e.to_string()))
430	    }) {
431	        Ok(result) => result,
432	        Err(diag) => Err(napi::Error::from_reason(diag.to_string())),
433	    }
434	}
435	
436	/// What a host needs to answer for one component: its documentation as `sessionDocgenInfo` returns it, and its own
437	/// diagnostics, each with `affects` set to the key. `{ key: { docgenInfo, diagnostics } }`; a key the session has no
438	/// component under is left out. A lazy session resolves each requested component now (in parallel), so a host learns
439	/// whether a component's props may be incomplete from the same call that returns them.
440	#[napi]
441	pub fn session_component_answers(session_id: u32, keys: Vec<String>) -> napi::Result<String> {
442	    match caliper_docgen_core::panic_guard::contain_panic("session_component_answers", move || {
443	        let session = SESSIONS.get(&session_id).map(|session| session.clone());
444	        let answers: serde_json::Map<String, serde_json::Value> = match session {
445	            Some(session) => {
446	                let answered = session.components(&keys);
447	                keys.into_iter()
448	                    .zip(answered)
449	                    .filter_map(|(key, answer)| {
450	                        let answer = answer?;
451	                        let answer = serde_json::json!({
452	                            "docgenInfo": caliper_docgen_core::pipeline::rdt::docgen_info(&answer.entry),
453	                            "diagnostics": answer.diagnostics,
454	                        });
455	                        Some((key, answer))
456	                    })
457	                    .collect()
458	            }
459	            None => serde_json::Map::new(),
460	        };

