81	/// The resident memory of a process in MiB: `/proc` where it exists, else `ps`. `None` when neither answers.
82	fn resident_mib(pid: u32) -> Option<u64> {
83	    let kib = match std::fs::read_to_string(format!("/proc/{pid}/status")) {
84	        Ok(status) => status
85	            .lines()
86	            .find_map(|line| line.strip_prefix("VmRSS:"))?
87	            .split_whitespace()
88	            .next()?
89	            .parse::<u64>()
90	            .ok()?,
91	        Err(_) => {
92	            let output = std::process::Command::new("ps").args(["-o", "rss=", "-p", &pid.to_string()]).output().ok()?;
93	            String::from_utf8_lossy(&output.stdout).trim().parse::<u64>().ok()?
94	        }
95	    };
96	    Some(kib / 1024)
97	}
