108	/// A warm `tsc` that answers for the components it is asked about. Dropping it stops the process.
109	pub struct OnDemand {
110	    jobs: Option<UnboundedSender<Job>>,
111	    thread: Option<JoinHandle<()>>,
112	    /// Receives once when the worker has stopped `tsc` and is about to exit.
113	    stopped: std::sync::Mutex<Option<mpsc::Receiver<()>>>,
114	    shutdown_wait: Duration,
115	}
116	
117	impl OnDemand {
118	    /// Starts the worker thread. The `tsc` process itself starts on the first request, or on [`OnDemand::warm_up`].
119	    pub fn new(config: OnDemandConfig) -> Self {
120	        let shutdown_wait = config.shutdown_wait;
121	        let (jobs, queue) = unbounded_channel();
122	        let (stopped_tx, stopped) = mpsc::channel();
123	        let thread = std::thread::Builder::new()
124	            .name("caliper-tsc".to_string())
125	            .spawn(move || {
126	                worker(config, queue);
127	                stopped_tx.send(()).ok();
128	            })
129	            .ok();
130	        Self {
131	            jobs: thread.as_ref().map(|_| jobs),
132	            thread,
133	            stopped: std::sync::Mutex::new(Some(stopped)),
134	            shutdown_wait,
135	        }
136	    }
137	
138	    /// Starts `tsc` in the background so the first request does not pay for it.
139	    pub fn warm_up(&self) {
140	        if let Some(jobs) = &self.jobs {
141	            jobs.send(Job::Warm).ok();
142	        }
143	    }
144	}
