146	impl SemanticProvider for OnDemand {
147	    fn request(&self, targets: Vec<SemanticTarget>) -> mpsc::Receiver<SemanticOutcome> {
148	        let (reply, receiver) = mpsc::sync_channel(1);
149	        match &self.jobs {
150	            Some(jobs) => {
151	                if let Err(refused) = jobs.send(Job::Answer { targets, reply }) {
152	                    if let Job::Answer { reply, .. } = refused.0 {
153	                        reply.send(SemanticOutcome::unavailable("the checker thread has stopped")).ok();
154	                    }
155	                }
156	            }
157	            None => {
158	                reply.send(SemanticOutcome::unavailable("could not start the checker thread")).ok();
159	            }
160	        }
161	        receiver
162	    }
163	}
