165	impl Drop for OnDemand {
166	    fn drop(&mut self) {
167	        // Closing the queue ends the worker loop, which shuts `tsc` down before the thread exits. A worker still inside
168	        // a long request is left to finish it: `tsc` stops when it does, or with this process.
169	        self.jobs.take();
170	        let receiver = self.stopped.get_mut().ok().and_then(Option::take);
171	        let stopped = receiver.is_none_or(|receiver| receiver.recv_timeout(self.shutdown_wait).is_ok());
172	        if let Some(thread) = self.thread.take() {
173	            if stopped {
174	                thread.join().ok();
175	            }
176	        }
177	    }
178	}
