180	fn worker(config: OnDemandConfig, mut queue: UnboundedReceiver<Job>) {
181	    let runtime = match tokio::runtime::Builder::new_current_thread().enable_all().build() {
182	        Ok(runtime) => runtime,
183	        Err(error) => {
184	            let reason = format!("could not start an async runtime: {error}");
185	            while let Some(job) = queue.blocking_recv() {
186	                if let Job::Answer { reply, .. } = job {
187	                    reply.send(SemanticOutcome::unavailable(reason.clone())).ok();
188	                }
189	            }
190	            return;
191	        }
192	    };
193	    runtime.block_on(async move {
194	        let mut checker = Checker::default();
195	        while let Some(job) = queue.recv().await {
196	            match job {
197	                Job::Warm => {
198	                    checker.ensure(&config).await.ok();
199	                }
200	                Job::Answer { targets, reply } => {
201	                    reply.send(checker.answer(&config, targets).await).ok();
202	                    // After the reply, so the caller never waits for the memory check or the replacement.
203	                    checker.maintain(&config).await;
204	                }
205	            }
206	        }
207	        if let Some(supervisor) = checker.supervisor.take() {
208	            supervisor.shutdown().await.ok();
209	        }
210	    });
211	}
