214	struct Checker {
215	    supervisor: Option<Supervisor>,
216	    /// Compiler options read once from the tsconfig for the running process.
217	    options: Option<serde_json::Value>,
218	    restarts: u32,
219	    /// Requests the running process has answered.
220	    served: u32,
221	    /// Why the checker cannot be used for the rest of the session.
222	    down: Option<String>,
223	}
224	
225	impl Checker {
226	    async fn ensure(&mut self, config: &OnDemandConfig) -> Result<(), String> {
227	        if let Some(reason) = &self.down {
228	            return Err(reason.clone());
229	        }
230	        if self.supervisor.as_ref().is_some_and(|supervisor| !supervisor.is_alive()) {
231	            if let Some(dead) = self.supervisor.take() {
232	                dead.shutdown().await.ok();
233	            }
234	            self.options = None;
235	            self.restarts += 1;
236	            if self.restarts > MAX_RESTARTS {
237	                return Err(self.stay_down("the checker kept crashing".to_string()));
238	            }
239	        }
240	        if self.supervisor.is_none() {
241	            let request = SemanticRequest {
242	                project_root: config.project_root.clone(),
243	                tsconfig: config.tsconfig.clone(),
244	                tsc_path: config.tsc_path.clone(),
245	                targets: Vec::new(),
246	                request_timeout: config.request_timeout,
247	                expected_versions: config.expected_versions,
248	                record_to: None,
249	                extra_env: config.extra_env.clone(),
250	                prepared_options: None,
251	            };
252	            let started = supervisor_config(&request).map_err(|reason| self.stay_down(reason))?;
253	            let supervisor = match Supervisor::spawn(started).await {
254	                Ok(supervisor) => supervisor,
255	                Err(error) => return Err(self.stay_down(error.to_string())),
256	            };
257	            // Initialize the session and read the compiler options once; every request after builds only its program.
258	            let tsconfig = config.tsconfig.as_ref().map(|path| path.as_str());
259	            match Rpc::prepare(&supervisor.client(), config.request_timeout, tsconfig).await {
260	                Ok(options) => self.options = Some(options),
261	                Err(error) => {
262	                    supervisor.shutdown().await.ok();
263	                    return Err(self.stay_down(format!("the checker did not initialize: {error}")));
264	                }
265	            }
266	            self.supervisor = Some(supervisor);
267	        }
268	        Ok(())
269	    }
270	
271	    fn stay_down(&mut self, reason: String) -> String {
272	        self.down = Some(reason.clone());
273	        reason
274	    }
275	
276	    async fn answer(&mut self, config: &OnDemandConfig, targets: Vec<SemanticTarget>) -> SemanticOutcome {
277	        if let Err(reason) = self.ensure(config).await {
278	            return SemanticOutcome::unavailable(reason);
279	        }
280	        let Some(supervisor) = self.supervisor.as_ref() else {
